  const removal=({'claim-remove':'claims','design-remove':'design','comparison-remove':'comparisons','decision-remove':'decisions','search-remove':'searches'})[action];if(removal){if(!confirm('Remove this record? Export a backup first if you need to retain it.'))return;w[removal]=w[removal].filter(r=>r.id!==value)}
  if(action==='impact-reviewed'){w.impact=false;w.decisions.push({id:uid(),date:now(),text:'Reviewed objectives, evidence, and proposal after the research question changed.'})}
  if(action==='snapshot')history(p,'Saved milestone');
  if(action==='snapshot-restore'){const s=w.snapshots.find(s=>s.id===value);if(!confirm('Restore this proposal text? The current draft will be saved as a milestone first.'))return;history(p,'Before restoring draft');p.proposal=s.proposal;w.impact=true}
  if(action==='review-export'){download('rei-review-package.md',report());return}
